package com.personal.assistant.module.dashboard.mapper;public final class DailyDashboardSql{private DailyDashboardSql(){}public static String sql(){return "select "+"(select count(*) from task_item where user_id=#{uid} and archived=false and coalesce(plan_time,deadline)::date=current_date and status not in ('COMPLETED','ARCHIVED')) today_task_count,"+"(select count(*) from task_item where user_id=#{uid} and archived=false and deadline<now() and status not in ('COMPLETED','ARCHIVED')) overdue_task_count,"+"(select count(*) from reminder where user_id=#{uid} and status='PENDING') pending_reminder_count,"+"(select count(*) from inbox_item where user_id=#{uid} and status='PENDING') pending_inbox_count,"+"(select count(*) from finance_transaction where user_id=#{uid} and confirmed=false) unconfirmed_transaction_count,"+"(select count(*) from dev_log where user_id=#{uid} and occurred_at>=now()-interval '7 days') recent_dev_log_count,"+"(select count(*) from learning_plan where user_id=#{uid} and status='IN_PROGRESS') active_learning_count,"+"(select count(*) from stock_fund_flow_snapshot s where s.user_id=#{uid} and s.quote_time=(select max(x.quote_time) from stock_fund_flow_snapshot x where x.watch_item_id=s.watch_item_id) and abs(coalesce(s.main_net_ratio,0))>=10) fund_flow_alert_count,"+"(select coalesce(sum(amount),0) from finance_transaction where user_id=#{uid} and direction='INCOME' and transaction_time>=date_trunc('month',now())) month_income,"+"(select coalesce(sum(amount),0) from finance_transaction where user_id=#{uid} and direction='EXPENSE' and transaction_time>=date_trunc('month',now())) month_expense,now() generated_at";}}
